const b = ($input.first() && $input.first().json && $input.first().json.body) || {};
const mus = b.mus || {};
const F = k => Number((mus[k] && (mus[k].f != null ? mus[k].f : mus[k])) || 0);
const names = { chest:'PEITO', shoulders:'OMBROS', back:'COSTAS', biceps:'BICEPS', triceps:'TRICEPS', core:'CORE', quads:'QUADRICEPS', hamstrings:'ISQUIO', glutes:'GLUTEOS', calves:'PANTURRILHA' };
const all = Object.keys(names).map(k => ({ k, f: F(k), n: names[k] }));
const top = all.sort((a, c) => c.f - a.f)[0] || { f: 0, n: '—' };
const push = (F('chest') + F('shoulders') + F('triceps')) / 3;
const pull = (F('back') + F('biceps')) / 2;
let flag = 'TECNICA', msg;
if (top.f >= 70) { flag = 'CUIDADO'; msg = top.n + ' a ' + Math.round(top.f) + '% de fadiga — o ponto mais carregado agora. Deixa recuperar antes de voltar a stressa-la.'; }
else if (Math.abs(push - pull) > 15) { const d = push > pull ? 'puxar (Pull)' : 'empurrar (Push)'; msg = 'Desequilibrio: falta trabalho de ' + d + '. Corpo simetrico puxa mais forte e lesiona menos — corrige hoje.'; }
else { msg = 'Distribuicao equilibrada. Execucao limpa e carga progressiva — e onde o ganho aparece e a lesao nao.'; }
return [{ json: { coach: 'CARIANI', flag, msg, topMuscle: top.n, topFat: Math.round(top.f) } }];
